# -*- coding: utf-8 -*-
# 10-cografya-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİNİN YERLEŞME VE NÜFUS DAĞILIŞINA ETKİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">SIK NÜFUSLU YERYÜZÜ ŞEKİLLERİ</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• Delta ovaları: Çukurova, Bafra, Çarşamba, Menemen</text>\n  <text x="34" y="112" font-size="11" fill="#1e3a8a">• Tektonik çöküntü ovaları: Bursa, Adapazarı, İnegöl, Erbaa</text>\n  <text x="34" y="136" font-size="11" fill="#1e3a8a">• Kıyı ovaları ve alçak platolar: Çatalca-Kocaeli Platosu</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">• Verimli alüvyal toprak, su kaynakları ve ılıman iklim</text>\n  <text x="34" y="184" font-size="11" fill="#1e3a8a">• Ulaşım ve sanayi tesislerinin kolay kurulabilmesi</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">SEYREK NÜFUSLU YERYÜZÜ ŞEKİLLERİ</text>\n  <text x="370" y="88" font-size="11" fill="#064e3b">• Sarp dağlık alanlar: Hakkâri, Doğu Karadeniz, Menteşe</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• Karstik ve engebeli sahalar: Teke ve Taşeli Platoları</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• Yüksek ve soğuk platolar: Erzurum-Kars-Ardahan</text>\n  <text x="370" y="160" font-size="11" fill="#064e3b">• Eğimin fazla, tarım alanlarının dar ve parçalı olması</text>\n  <text x="370" y="184" font-size="11" fill="#064e3b">• Doğu Karadeniz\'de dağınık, İç Anadolu\'da toplu yerleşme</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Yükselti, eğim ve bakı koşulları Türkiye\'de hem nüfus yoğunluğunu hem de yerleşme dokusunu doğrudan belirler.</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİNİN YERLEŞME VE NÜFUS DAĞILIŞINA ETKİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">SIK NÜFUSLU YERYÜZÜ ŞEKİLLERİ</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• Delta ovaları: Çukurova, Bafra, Çarşamba, Menemen</text>\n  <text x="34" y="112" font-size="11" fill="#1e3a8a">• Tektonik çöküntü ovaları: Bursa, Adapazarı, İnegöl, Erbaa</text>\n  <text x="34" y="136" font-size="11" fill="#1e3a8a">• Kıyı ovaları ve alçak platolar: Çatalca-Kocaeli Platosu</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">• Verimli alüvyal toprak, su kaynakları ve ılıman iklim</text>\n  <text x="34" y="184" font-size="11" fill="#1e3a8a">• Ulaşım ve sanayi tesislerinin kolay kurulabilmesi</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">SEYREK NÜFUSLU YERYÜZÜ ŞEKİLLERİ</text>\n  <text x="370" y="88" font-size="11" fill="#064e3b">• Sarp dağlık alanlar: Hakkâri, Doğu Karadeniz, Menteşe</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• Karstik ve engebeli sahalar: Teke ve Taşeli Platoları</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• Yüksek ve soğuk platolar: Erzurum-Kars-Ardahan</text>\n  <text x="370" y="160" font-size="11" fill="#064e3b">• Eğimin fazla, tarım alanlarının dar ve parçalı olması</text>\n  <text x="370" y="184" font-size="11" fill="#064e3b">• Doğu Karadeniz\'de dağınık, İç Anadolu\'da toplu yerleşme</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Yükselti, eğim ve bakı koşulları Türkiye\'de hem nüfus yoğunluğunu hem de yerleşme dokusunu doğrudan belirler.</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİ İLE TARIM VE HAYVANCILIK ETKİLEŞİMİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">TARIMSAL FAALİYETLERE ETKİSİ</text>\n  <text x="34" y="88" font-size="11" fill="#14532d">• Ova ve taban seviyesi düzlüklerinde makineli tarım kolaydır</text>\n  <text x="34" y="112" font-size="11" fill="#14532d">• Doğu Karadeniz ve Menteşe\'de eğim makineli tarımı kısıtlar</text>\n  <text x="34" y="136" font-size="11" fill="#14532d">• Yükselti arttıkça sıcaklık düşer, ürün olgunlaşması gecikir</text>\n  <text x="34" y="160" font-size="11" fill="#14532d">• Eğimli yamaçlarda erozyonu önlemek için taraçalama yapılır</text>\n  <text x="34" y="184" font-size="11" fill="#14532d">• Bakı etkisindeki güney yamaçlarda ürünler daha erken olgunlaşır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#d97706">HAYVANCILIK FAALİYETLERİNE ETKİSİ</text>\n  <text x="370" y="88" font-size="11" fill="#78350f">• Erzurum-Kars-Ardahan yüksek platoları: Büyükbaş mera</text>\n  <text x="370" y="112" font-size="11" fill="#78350f">• İç Anadolu ve Güneydoğu bozkır platoları: Küçükbaş (koyun)</text>\n  <text x="370" y="136" font-size="11" fill="#78350f">• Toroslar (Teke-Taşeli) engebeli makilik saha: Kıl keçisi</text>\n  <text x="370" y="160" font-size="11" fill="#78350f">• Menteşe ve Hakkâri dağlık çiçekli alanlar: Arıcılık</text>\n  <text x="370" y="184" font-size="11" fill="#78350f">• Karadeniz ve Toros yaylaları: Mevsimlik transhümans (yaylacılık)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Türkiye\'de kısa mesafelerde yükselti ve eğimin değişmesi tarımsal ürün çeşitliliğini artıran önemli bir etmendir.</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİ İLE TARIM VE HAYVANCILIK ETKİLEŞİMİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">TARIMSAL FAALİYETLERE ETKİSİ</text>\n  <text x="34" y="88" font-size="11" fill="#14532d">• Ova ve taban seviyesi düzlüklerinde makineli tarım kolaydır</text>\n  <text x="34" y="112" font-size="11" fill="#14532d">• Doğu Karadeniz ve Menteşe\'de eğim makineli tarımı kısıtlar</text>\n  <text x="34" y="136" font-size="11" fill="#14532d">• Yükselti arttıkça sıcaklık düşer, ürün olgunlaşması gecikir</text>\n  <text x="34" y="160" font-size="11" fill="#14532d">• Eğimli yamaçlarda erozyonu önlemek için taraçalama yapılır</text>\n  <text x="34" y="184" font-size="11" fill="#14532d">• Bakı etkisindeki güney yamaçlarda ürünler daha erken olgunlaşır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#d97706">HAYVANCILIK FAALİYETLERİNE ETKİSİ</text>\n  <text x="370" y="88" font-size="11" fill="#78350f">• Erzurum-Kars-Ardahan yüksek platoları: Büyükbaş mera</text>\n  <text x="370" y="112" font-size="11" fill="#78350f">• İç Anadolu ve Güneydoğu bozkır platoları: Küçükbaş (koyun)</text>\n  <text x="370" y="136" font-size="11" fill="#78350f">• Toroslar (Teke-Taşeli) engebeli makilik saha: Kıl keçisi</text>\n  <text x="370" y="160" font-size="11" fill="#78350f">• Menteşe ve Hakkâri dağlık çiçekli alanlar: Arıcılık</text>\n  <text x="370" y="184" font-size="11" fill="#78350f">• Karadeniz ve Toros yaylaları: Mevsimlik transhümans (yaylacılık)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Türkiye\'de kısa mesafelerde yükselti ve eğimin değişmesi tarımsal ürün çeşitliliğini artıran önemli bir etmendir.</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİNİN ULAŞIM AĞLARINA ETKİSİ VE GEÇİTLER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0f9ff" stroke="#0284c7" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0284c7">DOĞU - BATI VE KUZEY - GÜNEY ULAŞIMI</text>\n  <text x="34" y="88" font-size="11" fill="#0c4a6e">• Türkiye\'de dağlar genel olarak doğu-batı yönünde uzanır</text>\n  <text x="34" y="112" font-size="11" fill="#0c4a6e">• Doğu-batı yönlü oluklarda kara ve demir yolu maliyeti düşüktür</text>\n  <text x="34" y="136" font-size="11" fill="#0c4a6e">• Ege\'de graben ovaları kıyı ile iç kesim ulaşımını kolaylaştırır</text>\n  <text x="34" y="160" font-size="11" fill="#0c4a6e">• Karadeniz ve Akdeniz\'de kıyı-iç kesim ulaşımı zor ve maliyetlidir</text>\n  <text x="34" y="184" font-size="11" fill="#0c4a6e">• Viyadük, tünel ve köprülerle topoğrafik engeller aşılır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f5f3ff" stroke="#7c3aed" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#7c3aed">BAŞLICA DOĞAL VE TÜNEL GEÇİTLERİMİZ</text>\n  <text x="370" y="88" font-size="11" fill="#4c1d95">• Doğu Karadeniz: Zigana (Kalkanlı), Kop ve Ovit Tünelleri</text>\n  <text x="370" y="112" font-size="11" fill="#4c1d95">• Batı Karadeniz: Ecevit ve Ilgaz (15 Temmuz İstiklal) Geçitleri</text>\n  <text x="370" y="136" font-size="11" fill="#4c1d95">• Akdeniz (Batı/Orta Toroslar): Çubuk, Sertavul, Gülek</text>\n  <text x="370" y="160" font-size="11" fill="#4c1d95">• Akdeniz (Amanoslar): Belen Geçidi (Hatay - İskenderun)</text>\n  <text x="370" y="184" font-size="11" fill="#4c1d95">• Doğu Anadolu: Sakaltutan, Karabel ve Cankurtaran Geçitleri</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Kuzey Anadolu Dağları ve Toroslar\'daki geçitler ile tüneller kıyı limanlarını iç bölgelere bağlayan can damarlarıdır.</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİNİN ULAŞIM AĞLARINA ETKİSİ VE GEÇİTLER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0f9ff" stroke="#0284c7" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0284c7">DOĞU - BATI VE KUZEY - GÜNEY ULAŞIMI</text>\n  <text x="34" y="88" font-size="11" fill="#0c4a6e">• Türkiye\'de dağlar genel olarak doğu-batı yönünde uzanır</text>\n  <text x="34" y="112" font-size="11" fill="#0c4a6e">• Doğu-batı yönlü oluklarda kara ve demir yolu maliyeti düşüktür</text>\n  <text x="34" y="136" font-size="11" fill="#0c4a6e">• Ege\'de graben ovaları kıyı ile iç kesim ulaşımını kolaylaştırır</text>\n  <text x="34" y="160" font-size="11" fill="#0c4a6e">• Karadeniz ve Akdeniz\'de kıyı-iç kesim ulaşımı zor ve maliyetlidir</text>\n  <text x="34" y="184" font-size="11" fill="#0c4a6e">• Viyadük, tünel ve köprülerle topoğrafik engeller aşılır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f5f3ff" stroke="#7c3aed" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#7c3aed">BAŞLICA DOĞAL VE TÜNEL GEÇİTLERİMİZ</text>\n  <text x="370" y="88" font-size="11" fill="#4c1d95">• Doğu Karadeniz: Zigana (Kalkanlı), Kop ve Ovit Tünelleri</text>\n  <text x="370" y="112" font-size="11" fill="#4c1d95">• Batı Karadeniz: Ecevit ve Ilgaz (15 Temmuz İstiklal) Geçitleri</text>\n  <text x="370" y="136" font-size="11" fill="#4c1d95">• Akdeniz (Batı/Orta Toroslar): Çubuk, Sertavul, Gülek</text>\n  <text x="370" y="160" font-size="11" fill="#4c1d95">• Akdeniz (Amanoslar): Belen Geçidi (Hatay - İskenderun)</text>\n  <text x="370" y="184" font-size="11" fill="#4c1d95">• Doğu Anadolu: Sakaltutan, Karabel ve Cankurtaran Geçitleri</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Kuzey Anadolu Dağları ve Toroslar\'daki geçitler ile tüneller kıyı limanlarını iç bölgelere bağlayan can damarlarıdır.</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİNİN TURİZM VE ENERJİ ÜRETİMİNE ETKİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#ea580c">JEOMORFOLOJİK TURİZM DEĞERLERİ</text>\n  <text x="34" y="88" font-size="11" fill="#7c2d12">• Volkanik tüf aşınımı: Kapadokya (Nevşehir) Peribacaları</text>\n  <text x="34" y="112" font-size="11" fill="#7c2d12">• Traverten basamakları: Pamukkale (Denizli)</text>\n  <text x="34" y="136" font-size="11" fill="#7c2d12">• Karstik mağara ve kanyonlar: Damlataş, İnsuyu, Köprülü Kanyon</text>\n  <text x="34" y="160" font-size="11" fill="#7c2d12">• Kış (kayak) turizmi: Uludağ, Erciyes, Palandöken, Kartalkaya</text>\n  <text x="34" y="184" font-size="11" fill="#7c2d12">• Lagün (kıyı set) gölü ve plaj: Ölüdeniz (Fethiye)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">ENERJİ POTANSİYELİNE ETKİSİ</text>\n  <text x="370" y="88" font-size="11" fill="#064e3b">• Hidroelektrik (HES): Doğu Anadolu\'da derin vadiler ve yüksek eğim</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• Çoruh, Fırat (Atatürk, Keban, Karakaya) ve Dicle nehirleri</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• Jeotermal enerji: Batı Anadolu kırıklı (horst-graben) fay hatları</text>\n  <text x="370" y="160" font-size="11" fill="#064e3b">• Denizli (Sarayköy), Aydın (Germencik) jeotermal santralleri</text>\n  <text x="370" y="184" font-size="11" fill="#064e3b">• Rüzgâr enerjisi (RES): Boğazlar, Ege olukları ve yüksek sırtlar</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Engebeli topoğrafya ulaşımı zorlaştırsa da hidroelektrik enerji potansiyelini ve doğa turizmini güçlendirir.</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YERYÜZÜ ŞEKİLLERİNİN TURİZM VE ENERJİ ÜRETİMİNE ETKİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#ea580c">JEOMORFOLOJİK TURİZM DEĞERLERİ</text>\n  <text x="34" y="88" font-size="11" fill="#7c2d12">• Volkanik tüf aşınımı: Kapadokya (Nevşehir) Peribacaları</text>\n  <text x="34" y="112" font-size="11" fill="#7c2d12">• Traverten basamakları: Pamukkale (Denizli)</text>\n  <text x="34" y="136" font-size="11" fill="#7c2d12">• Karstik mağara ve kanyonlar: Damlataş, İnsuyu, Köprülü Kanyon</text>\n  <text x="34" y="160" font-size="11" fill="#7c2d12">• Kış (kayak) turizmi: Uludağ, Erciyes, Palandöken, Kartalkaya</text>\n  <text x="34" y="184" font-size="11" fill="#7c2d12">• Lagün (kıyı set) gölü ve plaj: Ölüdeniz (Fethiye)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">ENERJİ POTANSİYELİNE ETKİSİ</text>\n  <text x="370" y="88" font-size="11" fill="#064e3b">• Hidroelektrik (HES): Doğu Anadolu\'da derin vadiler ve yüksek eğim</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• Çoruh, Fırat (Atatürk, Keban, Karakaya) ve Dicle nehirleri</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• Jeotermal enerji: Batı Anadolu kırıklı (horst-graben) fay hatları</text>\n  <text x="370" y="160" font-size="11" fill="#064e3b">• Denizli (Sarayköy), Aydın (Germencik) jeotermal santralleri</text>\n  <text x="370" y="184" font-size="11" fill="#064e3b">• Rüzgâr enerjisi (RES): Boğazlar, Ege olukları ve yüksek sırtlar</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Engebeli topoğrafya ulaşımı zorlaştırsa da hidroelektrik enerji potansiyelini ve doğa turizmini güçlendirir.</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BEŞERÎ FAALİYETLERİN YERYÜZÜ ŞEKİLLERİNİ DEĞİŞTİRME ETKİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">KIYI DOLGU VE DEV ULAŞIM PROJELERİ</text>\n  <text x="34" y="88" font-size="11" fill="#7f1d1d">• Ordu-Giresun ve Rize-Artvin Havalimanları (Deniz dolgusu)</text>\n  <text x="34" y="112" font-size="11" fill="#7f1d1d">• Karadeniz Sahil Yolu ve İstanbul Yenikapı/Maltepe dolguları</text>\n  <text x="34" y="136" font-size="11" fill="#7f1d1d">• Avrasya Tüneli, Marmaray, Ovit ve Zigana tünelleri</text>\n  <text x="34" y="160" font-size="11" fill="#7f1d1d">• 1915 Çanakkale, Osmangazi ve Yavuz Sultan Selim Köprüleri</text>\n  <text x="34" y="184" font-size="11" fill="#7f1d1d">• Baraj gölleriyle akarsu vadilerinin su altında kalması</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">MADENCİLİK VE KENTLEŞME ETKİLERİ</text>\n  <text x="370" y="88" font-size="11" fill="#1e3a8a">• Açık işletme maden ocakları ve taş/mermer ocakları</text>\n  <text x="370" y="112" font-size="11" fill="#1e3a8a">• Yamaç dengesinin bozulmasıyla tetiklenen yapay heyelanlar</text>\n  <text x="370" y="136" font-size="11" fill="#1e3a8a">• Dere yataklarının doldurulması ve yapılaşmaya açılması</text>\n  <text x="370" y="160" font-size="11" fill="#1e3a8a">• Alüvyal tarım ovalarının sanayi ve konutla işgali</text>\n  <text x="370" y="184" font-size="11" fill="#1e3a8a">• İnsan (antropojen) etkisiyle topoğrafyanın hızla değişmesi</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">İnsan, modern teknolojiyle yeryüzü şekillerini en hızlı değiştiren jeomorfolojik etmen (antropojen etmen) hâline gelmiştir.</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BEŞERÎ FAALİYETLERİN YERYÜZÜ ŞEKİLLERİNİ DEĞİŞTİRME ETKİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">KIYI DOLGU VE DEV ULAŞIM PROJELERİ</text>\n  <text x="34" y="88" font-size="11" fill="#7f1d1d">• Ordu-Giresun ve Rize-Artvin Havalimanları (Deniz dolgusu)</text>\n  <text x="34" y="112" font-size="11" fill="#7f1d1d">• Karadeniz Sahil Yolu ve İstanbul Yenikapı/Maltepe dolguları</text>\n  <text x="34" y="136" font-size="11" fill="#7f1d1d">• Avrasya Tüneli, Marmaray, Ovit ve Zigana tünelleri</text>\n  <text x="34" y="160" font-size="11" fill="#7f1d1d">• 1915 Çanakkale, Osmangazi ve Yavuz Sultan Selim Köprüleri</text>\n  <text x="34" y="184" font-size="11" fill="#7f1d1d">• Baraj gölleriyle akarsu vadilerinin su altında kalması</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">MADENCİLİK VE KENTLEŞME ETKİLERİ</text>\n  <text x="370" y="88" font-size="11" fill="#1e3a8a">• Açık işletme maden ocakları ve taş/mermer ocakları</text>\n  <text x="370" y="112" font-size="11" fill="#1e3a8a">• Yamaç dengesinin bozulmasıyla tetiklenen yapay heyelanlar</text>\n  <text x="370" y="136" font-size="11" fill="#1e3a8a">• Dere yataklarının doldurulması ve yapılaşmaya açılması</text>\n  <text x="370" y="160" font-size="11" fill="#1e3a8a">• Alüvyal tarım ovalarının sanayi ve konutla işgali</text>\n  <text x="370" y="184" font-size="11" fill="#1e3a8a">• İnsan (antropojen) etkisiyle topoğrafyanın hızla değişmesi</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">İnsan, modern teknolojiyle yeryüzü şekillerini en hızlı değiştiren jeomorfolojik etmen (antropojen etmen) hâline gelmiştir.</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YAKIN ÇEVRE SORGULAMASI VE SÜRDÜRÜLEBİLİR ARAZİ PLANLAMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9333ea">YANLIŞ ARAZİ KULLANIMI RİSKLERİ</text>\n  <text x="34" y="88" font-size="11" fill="#581c87">• Birinci sınıf alüvyal ovalara fabrika ve toplu konut yapmak</text>\n  <text x="34" y="112" font-size="11" fill="#581c87">• Fay hatları ve gevşek alüvyon zemin üzerine çok katlı bina</text>\n  <text x="34" y="136" font-size="11" fill="#581c87">• Kurutulan göl ve taşkın yataklarını yerleşmeye açmak</text>\n  <text x="34" y="160" font-size="11" fill="#581c87">• Dik yamaçlardaki orman örtüsünü tahrip ederek heyelanı artırmak</text>\n  <text x="34" y="184" font-size="11" fill="#581c87">• Kıyı kumullarını ve lagün ekosistemlerini betonlaştırmak</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdfa" stroke="#0f766e" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">DOĞRU (SÜRDÜRÜLEBİLİR) PLANLAMA</text>\n  <text x="370" y="88" font-size="11" fill="#134e4a">• Tarım ovalarını yalnız tarımsal üretime ayırmak (Ovaları koruma)</text>\n  <text x="370" y="112" font-size="11" fill="#134e4a">• Sanayi ve yerleşmeleri sağlam kayalık yamaçlara kurmak</text>\n  <text x="370" y="136" font-size="11" fill="#134e4a">• Eğimli yamaçları ağaçlandırmak ve taraçalama yapmak</text>\n  <text x="370" y="160" font-size="11" fill="#134e4a">• Akarsu taşkın yataklarını yeşil kuşak ve rekreasyon alanı yapmak</text>\n  <text x="370" y="184" font-size="11" fill="#134e4a">• Arazi yetenek sınıflamasına uygun bütüncül planlama</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Sürdürülebilir arazi kullanımı, yeryüzü şekillerinin doğal potansiyeline ve sınırlarına saygı duymayı gerektirir.</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YAKIN ÇEVRE SORGULAMASI VE SÜRDÜRÜLEBİLİR ARAZİ PLANLAMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9333ea">YANLIŞ ARAZİ KULLANIMI RİSKLERİ</text>\n  <text x="34" y="88" font-size="11" fill="#581c87">• Birinci sınıf alüvyal ovalara fabrika ve toplu konut yapmak</text>\n  <text x="34" y="112" font-size="11" fill="#581c87">• Fay hatları ve gevşek alüvyon zemin üzerine çok katlı bina</text>\n  <text x="34" y="136" font-size="11" fill="#581c87">• Kurutulan göl ve taşkın yataklarını yerleşmeye açmak</text>\n  <text x="34" y="160" font-size="11" fill="#581c87">• Dik yamaçlardaki orman örtüsünü tahrip ederek heyelanı artırmak</text>\n  <text x="34" y="184" font-size="11" fill="#581c87">• Kıyı kumullarını ve lagün ekosistemlerini betonlaştırmak</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdfa" stroke="#0f766e" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">DOĞRU (SÜRDÜRÜLEBİLİR) PLANLAMA</text>\n  <text x="370" y="88" font-size="11" fill="#134e4a">• Tarım ovalarını yalnız tarımsal üretime ayırmak (Ovaları koruma)</text>\n  <text x="370" y="112" font-size="11" fill="#134e4a">• Sanayi ve yerleşmeleri sağlam kayalık yamaçlara kurmak</text>\n  <text x="370" y="136" font-size="11" fill="#134e4a">• Eğimli yamaçları ağaçlandırmak ve taraçalama yapmak</text>\n  <text x="370" y="160" font-size="11" fill="#134e4a">• Akarsu taşkın yataklarını yeşil kuşak ve rekreasyon alanı yapmak</text>\n  <text x="370" y="184" font-size="11" fill="#134e4a">• Arazi yetenek sınıflamasına uygun bütüncül planlama</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Sürdürülebilir arazi kullanımı, yeryüzü şekillerinin doğal potansiyeline ve sınırlarına saygı duymayı gerektirir.</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
